<?php get_header(); ?><main id="conteudo" class="shell"><section class="breaking"><b>AGORA</b><p>Últimas notícias da comunidade judaica em Portugal e no mundo.</p><a href="#noticias">Acompanhe <span>→</span></a></section><?php $lead=new WP_Query(['posts_per_page'=>1,'post_status'=>'publish','ignore_sticky_posts'=>true]); $side=new WP_Query(['posts_per_page'=>4,'offset'=>1,'post_status'=>'publish','ignore_sticky_posts'=>true]); ?><section class="hero-grid" aria-label="Destaques"><div><?php if($lead->have_posts()): while($lead->have_posts()):$lead->the_post(); ?><article class="hero-story story-card"><?php jnt_story_image('large','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1300&q=85'); ?><div class="hero-story__overlay"></div><div class="story-card__content"><span class="kicker"><?php echo esc_html(jnt_category()); ?></span><h1><a class="featured-title-link" href="<?php the_permalink(); ?>"><?php echo esc_html(jnt_excerpt_chars(get_the_title(), 75)); ?></a></h1><p><?php echo esc_html(jnt_excerpt_chars(get_the_excerpt(), 75)); ?></p><a class="hero-read-button" href="<?php the_permalink(); ?>">Ler artigo <span>→</span></a><span class="byline"><?php the_author(); ?> • <?php echo esc_html(get_the_date()); ?></span></div></article><?php endwhile; else: ?><article class="hero-story story-card"><div class="story-card__content"><span class="kicker">EM DESTAQUE</span><h1>Publique a primeira notícia para preencher esta área.</h1></div></article><?php endif; ?></div><div class="hero-side"><?php while($side->have_posts()):$side->the_post(); ?><article class="compact-story"><a class="compact-story__image" href="<?php the_permalink(); ?>"><?php jnt_story_image('thumbnail','https://images.unsplash.com/photo-1529070538774-1843cb3265df?auto=format&fit=crop&w=300&q=80'); ?></a><div><span class="kicker"><?php echo esc_html(jnt_category()); ?></span><h2><a href="<?php the_permalink(); ?>"><?php echo esc_html(jnt_excerpt_chars(get_the_title(), 55)); ?></a></h2><span class="byline"><?php echo esc_html(get_the_date()); ?></span></div></article><?php endwhile; ?></div></section><?php wp_reset_postdata(); ?><section id="noticias" class="section-block latest"><div class="section-heading"><h2>Mais recentes</h2><a href="<?php echo esc_url(get_permalink(get_option('page_for_posts')) ?: home_url('/')); ?>">Ver todas <span>→</span></a></div><div class="latest-grid"><?php $recent=new WP_Query(['posts_per_page'=>3,'offset'=>5,'post_status'=>'publish','ignore_sticky_posts'=>true,'orderby'=>'date','order'=>'DESC']); while($recent->have_posts()):$recent->the_post(); ?><article class="text-story"><span class="kicker"><?php echo esc_html(jnt_category()); ?></span><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),20)); ?></p><span class="byline"><?php echo esc_html(get_the_date()); ?></span></article><?php endwhile; wp_reset_postdata(); ?></div></section><section class="newsletter"><div><span class="eyebrow">NEWSLETTER</span><h2>Notícias que aproximam.</h2><p>Receba a seleção semanal na sua caixa de entrada.</p></div><?php get_search_form(); ?></section></main><?php get_footer(); ?>

